import React, { useMemo, useState } from "react";
import { useDispatch } from "react-redux";
import axios from "axios";
import { uploadImages /* , uploadVideo */ } from "../../api/requests/upload";
import { getFollowingTweets } from "../../redux/actions/tweetActions"; // optional refresh

axios.defaults.withCredentials = true;
const BASE = process.env.REACT_APP_API_URL || "http://localhost:5000";

export default function NewTweetForm() {
  const dispatch = useDispatch();
  const [text, setText] = useState("");
  const [files, setFiles] = useState([]);      // images
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");

  const previews = useMemo(() => files.map(f => URL.createObjectURL(f)), [files]);

  const onPick = (e) => {
    const selected = Array.from(e.target.files || []);
    const imgs = selected.filter(f => /^image\/(png|jpe?g|gif|webp)$/i.test(f.type));
    setFiles(prev => [...prev, ...imgs].slice(0, 4));
    e.target.value = "";
  };

  const removeAt = (i) => setFiles(prev => prev.filter((_, idx) => idx !== i));

  const submit = async (e) => {
    e.preventDefault();
    setErr("");
    if (!text.trim() && files.length === 0) { setErr("Write something or add an image"); return; }
    if (text.length > 280) { setErr("Max 280 characters"); return; }

    setLoading(true);
    try {
      let media = [];
      if (files.length) {
        // server must expose POST /uploads-api/image -> { urls: [...] }
        media = await uploadImages(files);
      }

      // POST /tweet/new
      const res = await axios.post(`${BASE}/tweet/new`, { body: text.trim(), media });
      if (res.status !== 200 && res.status !== 201) throw new Error("Failed to post");

      // reset + refresh following feed
      setText(""); setFiles([]);
      dispatch(getFollowingTweets(1));
    } catch (e) {
      setErr(e?.response?.data?.errors?.[0]?.msg || e.message || "Failed to post");
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={submit} className="new-tweet">
      <textarea
        className="new-tweet__input"
        placeholder="What's happening?"
        maxLength={280}
        value={text}
        onChange={(e) => setText(e.target.value)}
      />
      {previews.length > 0 && (
        <div className="new-tweet__media-grid">
          {previews.map((src, i) => (
            <div key={i} className="new-tweet__thumb">
              <img src={src} alt="" />
              <button type="button" className="new-tweet__x" onClick={() => removeAt(i)}>×</button>
            </div>
          ))}
        </div>
      )}
      <div className="new-tweet__actions">
        <label className="new-tweet__pick">
          📷
          <input hidden type="file" accept="image/*" multiple onChange={onPick} />
        </label>
        <div className="spacer" />
        <span className="count">{text.length}/280</span>
        <button disabled={loading || (!text.trim() && files.length === 0)}>
          {loading ? "Posting…" : "Tweet"}
        </button>
      </div>
      {err && <div className="new-tweet__error">{err}</div>}
    </form>
  );
}
